from pathlib import Path
p=Path('docs/SUPABASE_INTEGRATION.md');s=p.read_text().replace('App sessions are in memory, so restarting the process requires another sign-in; persisted cloud records remain.','App access/refresh credentials, selected semester and subject snapshot are persisted with Android Keystore AES-GCM in the no-backup directory. Reopening restores the app and reads Supabase directly; expired access tokens refresh automatically, with one retry on a rejected token. VTOP credentials are never persisted. VTOP reconnection is only for importing new university data, not viewing saved records.').replace('- Android assembleDebug, unit tests and lintDebug passed; 20 unit tests now pass.','- Android assembleDebug, unit tests and lintDebug passed; 23 unit tests cover academic mapping, login handling, persistent session restoration, automatic refresh/retry and sign-out cleanup.').replace('Sign in with your VTOP account, choose the enrolled semester under Home > My subjects, and tap Refresh.','Connect your VTOP account once. Subsequent opens and Refresh read saved Supabase data. Use Import from VTOP only when you want a new university import.').replace('- Deployed three SQL migrations and `studysync-session` Edge Function.','- Deployed three SQL migrations and `studysync-session` Edge Function.\n- Fixed the identity check to use the protected `/vtop/content` dashboard, normalize duplicate Set-Cookie headers, and follow only bounded same-origin redirects. The app reports connected only after cloud identity and academic storage succeed.\n- Registration numbers are normalized and unique; profile lookup reuses an existing account, and concurrent creation handles conflicts by re-reading the winner. Snapshot and membership imports use database upserts. Repeat-import rollback tests confirm no duplicates.')
p.write_text(s)
